<?php
declare(strict_types=1);
if(!defined('PLEKSI_APP')){http_response_code(404);exit;}
const ORDER_STATUSES=['İncelemede','Ödeme bekleniyor','Hazırlanıyor','Kargoya verildi','Tamamlandı','İptal edildi'];
function parse_order(array $o): array {foreach(['id','user_id','batch_id','version'] as $key)$o[$key]=(int)$o[$key];$o['total']=(float)$o['total'];$o['customer']=dec($o['customer']);$o['items']=dec($o['items']);return $o;}
function order_list(string $where='o.deleted_at IS NULL',array $params=[]): array {return array_map('parse_order',rows('SELECT o.*,b.day AS batch_day FROM ph_orders o JOIN ph_batches b ON b.id=o.batch_id WHERE '.$where.' ORDER BY o.id DESC',$params));}
function get_order(int $id,bool $lock=false): ?array {$r=one('SELECT o.*,b.day AS batch_day FROM ph_orders o JOIN ph_batches b ON b.id=o.batch_id WHERE o.id=?'.($lock?' FOR UPDATE':''),[$id]);return $r?parse_order($r):null;}
function build_items(mixed $items,array $buyer,array $editor,array $previous=[]): array {
 if(!is_array($items)||!count($items)||count($items)>100)fail('Sipariş 1–100 ürün kalemi içermeli.');$products=catalog();$saved=[];$seen=[];
 foreach($items as $i){if(!is_array($i))fail('Ürün kalemi geçersiz.');$p=null;foreach($products as $candidate)if($candidate['id']===($i['id']??null)){$p=$candidate;break;}$had=false;$old=null;foreach($previous as $x){if($x['id']===($i['id']??null))$had=true;if(isset($i['lineId'])&&$x['lineId']===$i['lineId']&&$x['id']===($i['id']??null))$old=$x;}
 if(!$p||(!$p['active']&&!$had)||!is_int($i['quantity']??null)||$i['quantity']<1||$i['quantity']>500)fail('Ürün veya adet geçersiz.');$text=is_string($i['personalization']??null)?trim($i['personalization']):'';if(mb_strlen($text)>200)fail('Yazı en fazla 200 karakter olabilir.');if($p['requireText']&&$text==='')fail($p['name'].' için yazı zorunludur.');$art=$i['artwork']??null;if($p['requireImage']&&!$art)fail($p['name'].' için görsel zorunludur.');if($art){if(!is_string($art))fail('Tasarım görseli geçersiz.');$image=one('SELECT user_id FROM ph_uploads WHERE id=?',[$art]);$was=false;foreach($previous as $x)if(($x['artwork']??null)===$art)$was=true;if(!$image||(!in_array((int)$image['user_id'],[(int)$buyer['id'],(int)$editor['id']],true)&&!$was))fail('Tasarım görseli geçersiz.');}
 $line=$old['lineId']??bin2hex(random_bytes(16));if(isset($seen[$line]))fail('Aynı ürün kalemi tekrarlanamaz.');$seen[$line]=true;$saved[]=['id'=>$p['id'],'lineId'=>$line,'name'=>$old['name']??$p['name'],'price'=>$old['price']??(is_dealer($buyer)?$p['dealerPrice']:$p['price']),'quantity'=>$i['quantity'],'retailPrice'=>$old['retailPrice']??$p['price'],'commissionPercent'=>$old['commissionPercent']??$p['commissionPercent'],'personalization'=>$text,'color'=>mb_substr(is_string($i['color']??null)?$i['color']:'',0,40),'artwork'=>$art];
 }return $saved;
}
function order_total(array $items,float $fee): float {return round(array_sum(array_map(fn($i)=>$i['price']*$i['quantity'],$items))+$fee,2);}
function order_profit(array $o): float {return round(array_sum(array_map(fn($i)=>(($i['retailPrice']??$i['price'])-$i['price'])*$i['quantity'],$o['items'])),2);}
function orders_route(string $route,string $method,array $b): void {global $user,$db;
 if($route==='/orders'&&$method==='GET'){$u=auth();$deleted=($_GET['deleted']??'')==='1';if($deleted&&$u['role']!=='admin')fail('Silinen kayıtları yalnızca yönetici görebilir.',403);out(order_list('o.deleted_at IS '.($deleted?'NOT NULL':'NULL').($u['role']==='admin'?'':' AND o.user_id=?'),$u['role']==='admin'?[]:[$u['id']]));}
 if($route==='/orders'&&$method==='POST'){$u=auth();$d=delivery(is_string($b['deliveryMethod']??null)?$b['deliveryMethod']:'pickup');$items=build_items($b['items']??null,$u,$u);$customer=['name'=>$u['name'],'phone'=>$u['phone'],'address'=>$u['neighborhood'].' / '.$u['district'].' / '.$u['city'],'city'=>$u['city'],'district'=>$u['district'],'neighborhood'=>$u['neighborhood'],'deliveryMethod'=>$d['id'],'deliveryLabel'=>$d['label'],'deliveryFee'=>$d['fee']];$total=order_total($items,$d['fee']);$r=atomic(function()use($u,$d,$items,$customer,$total,$db){$day=(new DateTimeImmutable('now',new DateTimeZone('Europe/Istanbul')))->format('Y-m-d');sql('INSERT INTO ph_batches(user_id,day) VALUES(?,?) ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id)',[$u['id'],$day]);$batch=(int)$db->lastInsertId();sql("INSERT INTO ph_orders(user_id,batch_id,customer,items,total,status) VALUES(?,?,?,?,?,'İncelemede')",[$u['id'],$batch,enc($customer),enc($items),$total]);$id=(int)$db->lastInsertId();notify('order',$id);return ['id'=>$id,'batchId'=>$batch,'total'=>$total,'delivery'=>$d];});out($r,201);}
 if(preg_match('~^/orders/(\d+)$~',$route,$m)&&$method==='PATCH'){$u=auth();$updated=atomic(function()use($m,$b,$u){$o=get_order((int)$m[1],true);if(!$o||$o['deleted_at']||($u['role']!=='admin'&&$o['user_id']!==(int)$u['id']))fail('Sipariş bulunamadı.',404);if($u['role']!=='admin'&&$o['status']!=='İncelemede')fail('Yalnızca size ait İncelemede durumundaki siparişleri düzenleyebilirsiniz.',403);if(!is_int($b['version']??null)||$b['version']!==$o['version'])fail('Sipariş başka bir işlemle değişti. Ekranı yenileyip tekrar deneyin.',409);$buyer=one('SELECT * FROM ph_users WHERE id=?',[$o['user_id']]);$items=build_items($b['items']??null,$buyer,$u,$o['items']);$d=delivery($b['deliveryMethod']??$o['customer']['deliveryMethod']);$customer=$o['customer'];$fee=$d['id']===$customer['deliveryMethod']?(float)$customer['deliveryFee']:$d['fee'];$customer=array_replace($customer,['deliveryMethod'=>$d['id'],'deliveryLabel'=>$d['label'],'deliveryFee'=>$fee]);if($u['role']==='admin'&&isset($b['customer']))foreach(['name','phone','address'] as $key){if(!valid_text($b['customer'][$key]??null,2,1000))fail('Alıcı bilgilerini kontrol edin.');$customer[$key]=trim($b['customer'][$key]);}sql('UPDATE ph_orders SET customer=?,items=?,total=?,version=version+1 WHERE id=?',[enc($customer),enc($items),order_total($items,$fee),$o['id']]);return get_order($o['id']);});out($updated);}
 if(preg_match('~^/admin/orders/(\d+)$~',$route,$m)&&$method==='PATCH'){if(!in_array($b['status']??null,ORDER_STATUSES,true))fail('Geçersiz durum.');if(!sql('UPDATE ph_orders SET status=?,version=version+1 WHERE id=? AND deleted_at IS NULL',[$b['status'],$m[1]])->rowCount())fail('Sipariş bulunamadı.',404);out(['ok'=>true]);}
 if($route==='/admin/orders/bulk'&&$method==='POST'){$ids=$b['ids']??null;$action=$b['action']??'';if(!is_array($ids)||!count($ids)||count($ids)>1000||count($ids)!==count(array_unique($ids)))fail('Geçerli siparişleri seçin.');foreach($ids as $id)if(!is_int($id)||$id<1)fail('Sipariş seçimi geçersiz.');if(!in_array($action,['status','delete','restore'],true)||($action==='status'&&!in_array($b['status']??null,ORDER_STATUSES,true)))fail('Geçersiz işlem.');sort($ids);atomic(function()use($ids,$action,$b){foreach($ids as $id){$o=get_order($id,true);if(!$o||($action==='restore'?!$o['deleted_at']:(bool)$o['deleted_at']))fail('Seçimdeki kayıtlar değişti. Listeyi yenileyin.',409);if($action==='status')sql('UPDATE ph_orders SET status=?,version=version+1 WHERE id=?',[$b['status'],$id]);elseif($action==='delete')sql('UPDATE ph_orders SET deleted_at=UTC_TIMESTAMP(),version=version+1 WHERE id=?',[$id]);else sql('UPDATE ph_orders SET deleted_at=NULL,version=version+1 WHERE id=?',[$id]);}});out(['updated'=>count($ids)]);}
 if(preg_match('~^/admin/batches/(\d+)$~',$route,$m)&&$method==='POST'){$action=$b['action']??'';if(!in_array($action,['status','delete'],true)||($action==='status'&&!in_array($b['status']??null,ORDER_STATUSES,true)))fail('Geçersiz işlem.');$count=atomic(function()use($action,$b,$m){$q=$action==='delete'?'UPDATE ph_orders SET deleted_at=UTC_TIMESTAMP(),version=version+1 WHERE batch_id=? AND deleted_at IS NULL':'UPDATE ph_orders SET status=?,version=version+1 WHERE batch_id=? AND deleted_at IS NULL';return sql($q,$action==='delete'?[$m[1]]:[$b['status'],$m[1]])->rowCount();});if(!$count)fail('Günlük dosya bulunamadı.',404);out(['updated'=>$count]);}
 if($route==='/dealer/summary'&&$method==='GET'){$u=auth();if(!is_dealer($u))fail('Onaylı bayi hesabı gerekiyor.',403);$orders=order_list('o.user_id=? AND o.deleted_at IS NULL',[$u['id']]);$result=['orders'=>count($orders),'batches'=>count(array_unique(array_column($orders,'batch_id'))),'pendingProfit'=>0,'realizedProfit'=>0,'totalPurchases'=>0];foreach($orders as $o){if($o['status']==='İptal edildi')continue;$result['totalPurchases']+=$o['total'];$result[$o['status']==='Tamamlandı'?'realizedProfit':'pendingProfit']+=order_profit($o);}foreach(['pendingProfit','realizedProfit','totalPurchases'] as $key)$result[$key]=round($result[$key],2);out($result);}
 if($route==='/admin/notifications'&&$method==='GET'){$list=[];$count=0;$ns=rows('SELECT * FROM ph_notifications ORDER BY id DESC LIMIT 200');foreach($ns as $n){$entry=['id'=>$n['type'].'-'.$n['id'],'type'=>$n['type'],'created'=>$n['created'],'read_at'=>$n['read_at']];if($n['type']==='order'){$o=get_order((int)$n['subject_id']);if(!$o||$o['deleted_at'])continue;$entry+=['order_id'=>$o['id'],'customer'=>$o['customer'],'total'=>$o['total'],'batch_id'=>$o['batch_id']];}else{$u=one("SELECT * FROM ph_users WHERE id=? AND role!='admin'",[$n['subject_id']]);if(!$u)continue;$entry+=['member_id'=>(int)$u['id'],'memberStatus'=>$u['dealer_status'],'customer'=>['name'=>$u['name'],'phone'=>$u['phone']]];}$list[]=$entry;}$count=(int)one("SELECT COUNT(*) AS n FROM ph_notifications n LEFT JOIN ph_orders o ON n.type='order' AND o.id=n.subject_id LEFT JOIN ph_users u ON n.type='member' AND u.id=n.subject_id WHERE n.read_at IS NULL AND ((n.type='order' AND o.id IS NOT NULL AND o.deleted_at IS NULL) OR (n.type='member' AND u.id IS NOT NULL AND u.role!='admin'))")['n'];out(['items'=>array_slice($list,0,100),'unread'=>$count]);}
 if($route==='/admin/notifications/read-all'&&$method==='POST'){sql('UPDATE ph_notifications SET read_at=UTC_TIMESTAMP() WHERE read_at IS NULL');out(['ok'=>true]);}
 if(preg_match('~^/admin/notifications/(order|member)-(\d+)/read$~',$route,$m)&&$method==='POST'){sql('UPDATE ph_notifications SET read_at=UTC_TIMESTAMP() WHERE id=? AND type=?',[$m[2],$m[1]]);out(['ok'=>true]);}
}
